#!/bin/sh

# PostgreSQL restore script for SQL.gz backups generated by postgres-backup.sh
#
# Usage:
#   postgres-restore.sh [backup_file] [target_db]
#
# Notes:
# - If backup_file is omitted, the latest backup in BACKUP_DIR is used.
# - If target_db exists, set RESTORE_OVERWRITE=1 to drop and recreate it.

set -eu

POSTGRES_HOST="${POSTGRES_HOST:-postgres}"
POSTGRES_PORT="${POSTGRES_PORT:-5432}"
POSTGRES_USER="${POSTGRES_USER:-postgres}"
POSTGRES_DB="${POSTGRES_DB:-maysar}"
BACKUP_DIR="${BACKUP_DIR:-/backups/postgres}"
ENCRYPTION_KEY="${ENCRYPTION_KEY:-}"

BACKUP_FILE="${1:-}"
TARGET_DB="${2:-$POSTGRES_DB}"

if [ -z "${PGPASSWORD:-}" ]; then
  echo "ERROR: PGPASSWORD must be set in the environment."
  exit 1
fi

if [ -z "$BACKUP_FILE" ]; then
  BACKUP_FILE="$(ls -1t "$BACKUP_DIR"/*.sql.gz "$BACKUP_DIR"/*.sql.gz.enc 2>/dev/null | head -n 1 || true)"
fi

if [ -z "$BACKUP_FILE" ]; then
  echo "ERROR: No backup file found in $BACKUP_DIR."
  exit 1
fi

if [ ! -f "$BACKUP_FILE" ]; then
  echo "ERROR: Backup file not found: $BACKUP_FILE"
  exit 1
fi

db_exists() {
  DB_NAME="$1"
  EXISTS="$(
    psql \
      --host="$POSTGRES_HOST" \
      --port="$POSTGRES_PORT" \
      --username="$POSTGRES_USER" \
      --dbname="postgres" \
      --tuples-only \
      --no-align \
      --command="SELECT 1 FROM pg_database WHERE datname = '$DB_NAME';" \
      | tr -d '[:space:]'
  )"
  [ "$EXISTS" = "1" ]
}

if db_exists "$TARGET_DB"; then
  if [ "${RESTORE_OVERWRITE:-0}" != "1" ]; then
    echo "ERROR: Target database '$TARGET_DB' already exists."
    echo "Set RESTORE_OVERWRITE=1 to drop and recreate it before restore."
    exit 1
  fi

  echo "Dropping existing database '$TARGET_DB'..."
  psql \
    --host="$POSTGRES_HOST" \
    --port="$POSTGRES_PORT" \
    --username="$POSTGRES_USER" \
    --dbname="postgres" \
    --command="SELECT pg_terminate_backend(pid) FROM pg_stat_activity WHERE datname = '$TARGET_DB' AND pid <> pg_backend_pid();" \
    >/dev/null

  dropdb \
    --host="$POSTGRES_HOST" \
    --port="$POSTGRES_PORT" \
    --username="$POSTGRES_USER" \
    "$TARGET_DB"
fi

if ! db_exists "$TARGET_DB"; then
  echo "Creating target database '$TARGET_DB'..."
  createdb \
    --host="$POSTGRES_HOST" \
    --port="$POSTGRES_PORT" \
    --username="$POSTGRES_USER" \
    "$TARGET_DB"
fi

echo "Restoring '$BACKUP_FILE' into '$TARGET_DB'..."

# Decrypt if encrypted
DECRYPTED_FILE=""
if [ "$(echo "$BACKUP_FILE" | sed 's/.*\.//')" = "enc" ]; then
  if [ -z "$ENCRYPTION_KEY" ]; then
    echo "ERROR: Backup file is encrypted but ENCRYPTION_KEY is not set."
    exit 1
  fi
  echo "Decrypting backup file..."
  DECRYPTED_FILE="$(mktemp)"
  openssl enc -d -aes-256-cbc -pbkdf2 -in "$BACKUP_FILE" -out "$DECRYPTED_FILE" -pass pass:"$ENCRYPTION_KEY"
  RESTORE_SOURCE="$DECRYPTED_FILE"
else
  RESTORE_SOURCE="$BACKUP_FILE"
fi

# Decompress
DECOMPRESSED_FILE="$(mktemp)"
echo "Decompressing backup file..."
gunzip -c "$RESTORE_SOURCE" > "$DECOMPRESSED_FILE"

# Restore using pg_restore (custom format from pg_dump -Fc)
pg_restore \
  --host="$POSTGRES_HOST" \
  --port="$POSTGRES_PORT" \
  --username="$POSTGRES_USER" \
  --dbname="$TARGET_DB" \
  --no-owner \
  --no-privileges \
  "$DECOMPRESSED_FILE" || true

# Clean up temp files
rm -f "$DECOMPRESSED_FILE"
if [ -n "$DECRYPTED_FILE" ]; then
  rm -f "$DECRYPTED_FILE"
fi

echo "Restore completed successfully for database '$TARGET_DB'."
